// Agent Task & Reminder endpoints - PB 0.35 compatible.
// Helpers are duplicated inside each route because PB 0.35 callback scope is isolated.

// GET /api/agent/tasks
routerAdd('GET', '/api/agent/tasks', function(c) {
  function auth() { var info=c.requestInfo(); var headers=info.headers||{}; var hh=headers.authorization||headers.Authorization||''; if(!hh)return{error:'Missing API key',status:401}; var p=String(hh).split(' '); if(p.length!==2||p[0].toLowerCase()!=='bearer')return{error:'Invalid Authorization header',status:401}; var raw=p[1].trim(); if(!raw)return{error:'Empty API key',status:401}; var hashed=$security.sha256(raw); var keys=$app.findRecordsByFilter('api_tokens','token_hash = {:hash}','',1,0,{hash:hashed}); if(keys.length===0)return{error:'Invalid API key',status:401}; var key=keys[0]; var en=key.get('enabled'); if(en===false||en===0||en==='false')return{error:'Revoked',status:401}; var ex=key.get('expires_at'); if(ex){var em=new Date(String(ex)).getTime(); if(em>0&&em<Date.now())return{error:'Expired',status:401};} var uid=String(key.get('user')||''); if(!uid)return{error:'No owner',status:401}; var user=null; try{user=$app.findRecordById('users',uid);}catch(e){} if(!user)return{error:'User not found',status:401}; var ms=String(user.get('member_status')||'active'); if(ms==='blocked')return{error:'Token owner account is blocked',status:403}; if(ms==='pending_approval')return{error:'Token owner is pending approval',status:403}; var fid=String(user.get('family_id')||''); if(!fid)return{error:'No family',status:401}; return{uid:uid,fid:fid,key:key,user:user}; }
  function hasScope(key,scope){var text='';try{text=String(key.getString('permissions')||'');}catch(e){}if(!text){try{text=String(key.getString('scopes')||'');}catch(e){}}var list=[];try{list=JSON.parse(text||'[]');}catch(e){list=text?text.split(','):[];}if(!Array.isArray(list))return false;var fam=scope.split(':')[0]+':*';for(var i=0;i<list.length;i++){var s=String(list[i]||'').trim();if(s==='*'||s===scope||s===fam)return true;if(scope.indexOf('entries:')===0&&(s==='tasks:*'||s==='groceries:*'))return true;}return false;}
  function canAccessTaskForUser(record,user){if(!record||!user)return false;var userId=user.id;var ownerId=String(record.get('user')||'');if(ownerId===userId)return true;if(record.get('is_private')===true||record.get('is_private')===1||record.get('is_private')==='true')return false;var familyId=String(user.get('family_id')||'');if(!familyId||!ownerId)return false;try{if(String($app.findRecordById('users',ownerId).get('family_id')||'')!==familyId)return false;}catch(e){return false;}var labelIds=record.get('label')||record.get('labels')||[];if(!Array.isArray(labelIds))labelIds=labelIds?[String(labelIds)]:[];var labels=[];for(var i=0;i<labelIds.length;i++){try{labels.push($app.findRecordById('labels',String(labelIds[i]||'')));}catch(e){return false;}}if(labelIds.length>1){for(var mi=0;mi<labels.length;mi++){var mv=String(labels[mi].get('visibility')||(labels[mi].get('is_private')?'private':'family'));if(mv!=='family')return false;}}for(var li=0;li<labels.length;li++){var label=labels[li];var visibility=String(label.get('visibility')||(label.get('is_private')?'private':'family'));var labelOwner=String(label.get('owner')||label.get('user')||'');var labelFamily=String(label.get('family')||'');if(!labelFamily&&labelOwner){try{labelFamily=String($app.findRecordById('users',labelOwner).get('family_id')||'');}catch(e){return false;}}if(visibility==='private'&&labelOwner!==userId)return false;if(visibility==='shared'){var shared=label.get('shared_with')||[];if(!Array.isArray(shared))shared=shared?[String(shared)]:[];if(labelOwner!==userId&&shared.indexOf(userId)===-1)return false;}if(visibility==='family'&&labelFamily!==familyId)return false;}return true;}
  try { var a=auth(); if(a.error)return c.json(a.status||401,{error:a.error}); if(!hasScope(a.key,'entries:read')&&!hasScope(a.key,'tasks:read'))return c.json(403,{error:'Missing scope'}); var q=c.requestInfo().query||{}; var st=String(q.status||'').trim(); var allowedStatuses=['todo','in_progress','done','cancelled']; if(st&&allowedStatuses.indexOf(st)===-1)return c.json(400,{error:'Invalid status'}); var params={familyId:a.fid,userId:a.uid}; var filter='user.family_id = {:familyId} && assigned_to = {:userId}'; if(st){filter+=' && status = {:status}';params.status=st;} var requestedSort=String(q.sort||'-created'); var allowedSorts=['created','-created','updated','-updated','due_date','-due_date','priority','-priority']; var sort=allowedSorts.indexOf(requestedSort)!==-1?requestedSort:'-created'; var tasks=$app.findRecordsByFilter('tasks',filter,sort,100,0,params); var r=[]; for(var i=0;i<tasks.length;i++){var t=tasks[i];if(!canAccessTaskForUser(t,a.user))continue;r.push({id:t.id,title:t.get('title'),status:t.get('status'),created:String(t.get('created'))});} return c.json(200,{tasks:r}); } catch(e){return c.json(500,{error:String(e)});}
});

// PATCH /api/agent/tasks/{id}
routerAdd('PATCH', '/api/agent/tasks/{id}', function(c) {
  function auth() { var info=c.requestInfo(); var headers=info.headers||{}; var hh=headers.authorization||headers.Authorization||''; if(!hh)return{error:'Missing API key',status:401}; var p=String(hh).split(' '); if(p.length!==2||p[0].toLowerCase()!=='bearer')return{error:'Invalid Authorization header',status:401}; var raw=p[1].trim(); if(!raw)return{error:'Empty API key',status:401}; var hashed=$security.sha256(raw); var keys=$app.findRecordsByFilter('api_tokens','token_hash = {:hash}','',1,0,{hash:hashed}); if(keys.length===0)return{error:'Invalid API key',status:401}; var key=keys[0]; var en=key.get('enabled'); if(en===false||en===0||en==='false')return{error:'Revoked',status:401}; var ex=key.get('expires_at'); if(ex){var em=new Date(String(ex)).getTime(); if(em>0&&em<Date.now())return{error:'Expired',status:401};} var uid=String(key.get('user')||''); if(!uid)return{error:'No owner',status:401}; var user=null; try{user=$app.findRecordById('users',uid);}catch(e){} if(!user)return{error:'User not found',status:401}; var ms=String(user.get('member_status')||'active'); if(ms==='blocked')return{error:'Token owner account is blocked',status:403}; if(ms==='pending_approval')return{error:'Token owner is pending approval',status:403}; var fid=String(user.get('family_id')||''); if(!fid)return{error:'No family',status:401}; return{uid:uid,fid:fid,key:key,user:user}; }
  function hasScope(key,scope){var text='';try{text=String(key.getString('permissions')||'');}catch(e){}if(!text){try{text=String(key.getString('scopes')||'');}catch(e){}}var list=[];try{list=JSON.parse(text||'[]');}catch(e){list=text?text.split(','):[];}if(!Array.isArray(list))return false;var fam=scope.split(':')[0]+':*';for(var i=0;i<list.length;i++){var s=String(list[i]||'').trim();if(s==='*'||s===scope||s===fam)return true;if(scope.indexOf('entries:')===0&&(s==='tasks:*'||s==='groceries:*'))return true;}return false;}
  function canAccessTaskForUser(record,user){if(!record||!user)return false;var userId=user.id;var ownerId=String(record.get('user')||'');if(ownerId===userId)return true;if(record.get('is_private')===true||record.get('is_private')===1||record.get('is_private')==='true')return false;var familyId=String(user.get('family_id')||'');if(!familyId||!ownerId)return false;try{if(String($app.findRecordById('users',ownerId).get('family_id')||'')!==familyId)return false;}catch(e){return false;}var labelIds=record.get('label')||record.get('labels')||[];if(!Array.isArray(labelIds))labelIds=labelIds?[String(labelIds)]:[];var labels=[];for(var i=0;i<labelIds.length;i++){try{labels.push($app.findRecordById('labels',String(labelIds[i]||'')));}catch(e){return false;}}if(labelIds.length>1){for(var mi=0;mi<labels.length;mi++){var mv=String(labels[mi].get('visibility')||(labels[mi].get('is_private')?'private':'family'));if(mv!=='family')return false;}}for(var li=0;li<labels.length;li++){var label=labels[li];var visibility=String(label.get('visibility')||(label.get('is_private')?'private':'family'));var labelOwner=String(label.get('owner')||label.get('user')||'');var labelFamily=String(label.get('family')||'');if(!labelFamily&&labelOwner){try{labelFamily=String($app.findRecordById('users',labelOwner).get('family_id')||'');}catch(e){return false;}}if(visibility==='private'&&labelOwner!==userId)return false;if(visibility==='shared'){var shared=label.get('shared_with')||[];if(!Array.isArray(shared))shared=shared?[String(shared)]:[];if(labelOwner!==userId&&shared.indexOf(userId)===-1)return false;}if(visibility==='family'&&labelFamily!==familyId)return false;}return true;}
  try { var a=auth(); if(a.error)return c.json(a.status||401,{error:a.error}); if(!hasScope(a.key,'entries:write')&&!hasScope(a.key,'tasks:write'))return c.json(403,{error:'Missing scope'}); var id=c.request.pathValue('id'); var t=$app.findRecordById('tasks',id); if(!t)return c.json(404,{error:'Not found'}); if(String(t.get('assigned_to')||'')!==a.uid)return c.json(403,{error:'Not assigned'}); var owner=null; try{owner=$app.findRecordById('users',String(t.get('user')||''));}catch(e){} if(!owner||String(owner.get('family_id')||'')!==a.fid)return c.json(403,{error:'Outside family'}); if(!canAccessTaskForUser(t,a.user))return c.json(403,{error:'Task is private'}); var info=c.requestInfo(); var body=info.body||info.data||{}; var ns=String(body.status||'').trim(); if(ns){t.set('status',ns); if(ns==='done')t.set('completed_at',new Date().toISOString());} $app.save(t); return c.json(200,{id:t.id,status:t.get('status')}); } catch(e){return c.json(500,{error:String(e)});}
});

// POST /api/agent/reminders
routerAdd('POST', '/api/agent/reminders', function(c) {
  function auth() { var info=c.requestInfo(); var headers=info.headers||{}; var hh=headers.authorization||headers.Authorization||''; if(!hh)return{error:'Missing API key',status:401}; var p=String(hh).split(' '); if(p.length!==2||p[0].toLowerCase()!=='bearer')return{error:'Invalid Authorization header',status:401}; var raw=p[1].trim(); if(!raw)return{error:'Empty API key',status:401}; var hashed=$security.sha256(raw); var keys=$app.findRecordsByFilter('api_tokens','token_hash = {:hash}','',1,0,{hash:hashed}); if(keys.length===0)return{error:'Invalid API key',status:401}; var key=keys[0]; var en=key.get('enabled'); if(en===false||en===0||en==='false')return{error:'Revoked',status:401}; var ex=key.get('expires_at'); if(ex){var em=new Date(String(ex)).getTime(); if(em>0&&em<Date.now())return{error:'Expired',status:401};} var uid=String(key.get('user')||''); if(!uid)return{error:'No owner',status:401}; var user=null; try{user=$app.findRecordById('users',uid);}catch(e){} if(!user)return{error:'User not found',status:401}; var ms=String(user.get('member_status')||'active'); if(ms==='blocked')return{error:'Token owner account is blocked',status:403}; if(ms==='pending_approval')return{error:'Token owner is pending approval',status:403}; var fid=String(user.get('family_id')||''); if(!fid)return{error:'No family',status:401}; return{uid:uid,fid:fid,key:key,user:user}; }
  function hasScope(key,scope){var text='';try{text=String(key.getString('permissions')||'');}catch(e){}if(!text){try{text=String(key.getString('scopes')||'');}catch(e){}}var list=[];try{list=JSON.parse(text||'[]');}catch(e){list=text?text.split(','):[];}if(!Array.isArray(list))return false;var fam=scope.split(':')[0]+':*';for(var i=0;i<list.length;i++){var s=String(list[i]||'').trim();if(s==='*'||s===scope||s===fam)return true;if(scope.indexOf('entries:')===0&&(s==='tasks:*'||s==='groceries:*'))return true;}return false;}
  function canAccessTaskForUser(record,user){if(!record||!user)return false;var userId=user.id;var ownerId=String(record.get('user')||'');if(ownerId===userId)return true;if(record.get('is_private')===true||record.get('is_private')===1||record.get('is_private')==='true')return false;var familyId=String(user.get('family_id')||'');if(!familyId||!ownerId)return false;try{if(String($app.findRecordById('users',ownerId).get('family_id')||'')!==familyId)return false;}catch(e){return false;}var labelIds=record.get('label')||record.get('labels')||[];if(!Array.isArray(labelIds))labelIds=labelIds?[String(labelIds)]:[];var labels=[];for(var i=0;i<labelIds.length;i++){try{labels.push($app.findRecordById('labels',String(labelIds[i]||'')));}catch(e){return false;}}if(labelIds.length>1){for(var mi=0;mi<labels.length;mi++){var mv=String(labels[mi].get('visibility')||(labels[mi].get('is_private')?'private':'family'));if(mv!=='family')return false;}}for(var li=0;li<labels.length;li++){var label=labels[li];var visibility=String(label.get('visibility')||(label.get('is_private')?'private':'family'));var labelOwner=String(label.get('owner')||label.get('user')||'');var labelFamily=String(label.get('family')||'');if(!labelFamily&&labelOwner){try{labelFamily=String($app.findRecordById('users',labelOwner).get('family_id')||'');}catch(e){return false;}}if(visibility==='private'&&labelOwner!==userId)return false;if(visibility==='shared'){var shared=label.get('shared_with')||[];if(!Array.isArray(shared))shared=shared?[String(shared)]:[];if(labelOwner!==userId&&shared.indexOf(userId)===-1)return false;}if(visibility==='family'&&labelFamily!==familyId)return false;}return true;}
  try { var a=auth(); if(a.error)return c.json(a.status||401,{error:a.error}); if(!hasScope(a.key,'entries:write')&&!hasScope(a.key,'calendar:write'))return c.json(403,{error:'Missing scope'}); var info=c.requestInfo(); var body=info.body||info.data||{}; var title=String(body.title||'').trim(); if(!title)return c.json(400,{error:'Title required'}); var rt=String(body.reminder_time||'').trim(); if(!rt)return c.json(400,{error:'reminder_time required'}); var coll=$app.findCollectionByNameOrId('reminders'); var rec=new Record(coll); rec.set('title',title); rec.set('reminder_time',rt); rec.set('user',a.uid); $app.save(rec); return c.json(201,{id:rec.id,title:title,reminder_time:rt}); } catch(e){return c.json(500,{error:String(e)});}
});

